			$bonus_reward_config = $this->config->get('module_bonus_reward_manufacturer');
			$config_bonus_reward = isset($bonus_reward_config[$product_info['manufacturer_id']]) ? $bonus_reward_config[$product_info['manufacturer_id']] : 0;
		}

		if (!empty($config_bonus_reward['customer_group'][$customer_group_id])) {
			$price = (float)($product_info['special'] > 0 ? $product_info['special'] : $product_info['price']);
			$data['reward'] = (int)($price * ($config_bonus_reward['customer_group'][$customer_group_id] / 100));
		} else {
			$data['reward'] = '';
		}
	}
} else {
	$data['reward'] = $product_info['reward'];
}

